#include "controller_navigation_state.h"
void controller_navigation_state_reset(ControllerRuntime *r, double x, double z) { if (!r) return; r->navigation_mode=NAV_MODE_IDLE; r->navigation_waypoint_index=-1; r->navigation_segment_start_x=x; r->navigation_segment_start_z=z; r->lidar_priority_turn_sign=0; r->lidar_priority_hold_steps=0; controller_avoidance_state_reset(&r->avoidance,x,z); r->mapping_survey.replan_cooldown_steps=0; }
void controller_navigation_state_begin(ControllerRuntime *r,int w,double x,double z) { if (!r) return; r->navigation_waypoint_index=w; r->navigation_segment_start_x=x; r->navigation_segment_start_z=z; r->navigation_mode=NAV_MODE_TURN; }
void controller_navigation_state_ensure(ControllerRuntime *r,double x,double z) { if (r && r->navigation_waypoint_index != r->current_waypoint_index) controller_navigation_state_begin(r,r->current_waypoint_index,x,z); }
void controller_navigation_state_clear_local(ControllerRuntime *r,double x,double z) { if (!r) return; r->lidar_priority_turn_sign=0; r->lidar_priority_hold_steps=0; double px=r->avoidance.prev_x,pz=r->avoidance.prev_z; controller_avoidance_state_reset(&r->avoidance,x,z); r->avoidance.prev_x=px;r->avoidance.prev_z=pz; }
